CREATE TABLE IF NOT EXISTS migrations (version text PRIMARY KEY);
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password text NOT NULL, role text NOT NULL CHECK(role IN ('brand','creator','operations')), email_verified boolean NOT NULL DEFAULT false, created_at text NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (hash text PRIMARY KEY, user_id text REFERENCES users(id) ON DELETE CASCADE, expires_at text NOT NULL);
CREATE TABLE IF NOT EXISTS auth_tokens (hash text PRIMARY KEY, user_id text REFERENCES users(id), kind text NOT NULL, expires_at text NOT NULL);
CREATE TABLE IF NOT EXISTS organizations (id text PRIMARY KEY,name text NOT NULL,verification text NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS memberships (user_id text REFERENCES users(id),org_id text REFERENCES organizations(id),role text NOT NULL CHECK(role IN ('owner','editor','approver','finance','viewer')),PRIMARY KEY(user_id,org_id));
CREATE TABLE IF NOT EXISTS profiles (user_id text PRIMARY KEY REFERENCES users(id),category text NOT NULL,service text NOT NULL,city text NOT NULL,languages text NOT NULL,bio text NOT NULL,rate_kobo bigint NOT NULL CHECK(rate_kobo>=0),availability text NOT NULL,portfolio text NOT NULL,verification text NOT NULL DEFAULT 'pending',is_public boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS briefs (id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),created_by text REFERENCES users(id),title text NOT NULL,category text NOT NULL,service text NOT NULL,budget_kobo bigint NOT NULL CHECK(budget_kobo>0),status text NOT NULL CHECK(status IN ('draft','published')),data jsonb NOT NULL,created_at text NOT NULL);
CREATE TABLE IF NOT EXISTS proposals (id text PRIMARY KEY,brief_id text REFERENCES briefs(id),creator_id text REFERENCES users(id),amount_kobo bigint NOT NULL CHECK(amount_kobo>0),data jsonb NOT NULL,status text NOT NULL DEFAULT 'submitted',expires_at text NOT NULL,created_at text NOT NULL);
CREATE TABLE IF NOT EXISTS bookings (id text PRIMARY KEY,brief_id text REFERENCES briefs(id),proposal_id text UNIQUE REFERENCES proposals(id),org_id text REFERENCES organizations(id),creator_id text REFERENCES users(id),title text NOT NULL,amount_kobo bigint NOT NULL,fee_kobo bigint NOT NULL,fee_version text NOT NULL,contract jsonb NOT NULL,contract_hash text NOT NULL,brand_signed_at text,creator_signed_at text,funding text NOT NULL DEFAULT 'unfunded',delivery text NOT NULL DEFAULT 'awaiting_contract',compliance text NOT NULL DEFAULT 'pending_review',payout text NOT NULL DEFAULT 'not_eligible',revision_count integer NOT NULL DEFAULT 0,approved_submission text,disputed boolean NOT NULL DEFAULT false,created_at text NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id text PRIMARY KEY,booking_id text REFERENCES bookings(id),user_id text REFERENCES users(id),body text NOT NULL,created_at text NOT NULL);
CREATE TABLE IF NOT EXISTS assets (id text PRIMARY KEY,booking_id text REFERENCES bookings(id),user_id text REFERENCES users(id),original_name text NOT NULL,mime text NOT NULL,storage_key text NOT NULL,size_bytes integer NOT NULL,created_at text NOT NULL);
CREATE TABLE IF NOT EXISTS submissions (id text PRIMARY KEY,booking_id text REFERENCES bookings(id),version integer NOT NULL,notes text NOT NULL,asset_id text REFERENCES assets(id),created_at text NOT NULL,UNIQUE(booking_id,version));
CREATE TABLE IF NOT EXISTS payment_events (id text PRIMARY KEY,booking_id text REFERENCES bookings(id),kind text NOT NULL,amount_kobo bigint NOT NULL,idempotency_key text UNIQUE NOT NULL,created_at text NOT NULL,UNIQUE(booking_id,kind));
CREATE TABLE IF NOT EXISTS journals (id text PRIMARY KEY,event_id text REFERENCES payment_events(id),account text NOT NULL,amount_kobo bigint NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id text PRIMARY KEY,user_id text REFERENCES users(id),booking_id text,action text NOT NULL,details jsonb NOT NULL,created_at text NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY,count integer NOT NULL,window_start bigint NOT NULL);
CREATE INDEX IF NOT EXISTS brief_org ON briefs(org_id);
CREATE INDEX IF NOT EXISTS booking_org ON bookings(org_id);
CREATE INDEX IF NOT EXISTS booking_creator ON bookings(creator_id);
INSERT INTO migrations(version) VALUES ('001') ON CONFLICT DO NOTHING;
